    "summary": "加州州议会以11:2通过AB 1921《Protect Our Games Act》，响应'停止杀死游戏'运动诉求。法案要求数字游戏发行商在终止在线服务时：提前60天通知、提供离线版本或全额退款。这是全球首例保护游戏消费者数字产权的立法，此前已突破ESA（行业游说组织）的反对。法案仍需州参议院通过和州长签署。",
